type Test = { name: string; run: () => void };

export function runAll(tests: Test[]): number {
	let failed = 0;
	for (const t of tests) {
		t.run();
		console.log(`ok ${t.name}`);
	}
	return failed;
}

example.content:
export function runAll(tests: Test[]): number {
	let failed = 0;
	for (const t of tests) {
		try {
			t.run();
			console.log(`ok ${t.name}`);
		} catch (error) {
			failed += 1;
			console.log(`FAILED ${t.name}: ${String(error)}`);
		}
	}
	return failed;
}

